def d(p,t): return abs(p[0]-t[0])+abs(p[1]-t[1])+abs(p[2]-t[2])
def raw_fill_mask(r,f):
    W=80; pts=[]; grid=[[0]*W for _ in range(W)]
    for y in range(W):
