    minx=min(x for x,y in pts); maxx=max(x for x,y in pts); miny=min(y for x,y in pts); maxy=max(y for x,y in pts)
    return grid,minx,miny,maxx,maxy

def norm_mask(grid,minx,miny,maxx,maxy,n=32):
    out=[]; w=maxx-minx+1; h=maxy-miny+1
    for yy in range(n):
        row=0
        for xx in range(n):
            x0=minx+xx*w//n; x1=minx+(xx+1)*w//n; y0=miny+yy*h//n; y1=miny+(yy+1)*h//n
            cnt=tot=0
            for y in range(y0,y1):
                for x in range(x0,x1):
                    cnt+=grid[y][x]; tot+=1
            if cnt>=tot*0.35: row|=1<<xx
        out.append(row)
    return out

def hd(a,b): return sum((x^y).bit_count() for x,y in zip(a,b))

